import java.io.IOException;
import java.util.*;

public class Test {
    int readInt() {
        int val = 0;
        boolean negativeFlag = false;
        try {
            boolean startedReading = false;
            for (int ch = 0; (ch = System.in.read()) != -1; ) {
                if (ch == '-') {
                    startedReading = true;
                    negativeFlag = true;
                    continue;
                } else if (ch >= '0' && ch <= '9') {
                    startedReading = true;
                    val = val * 10 + ch - '0';
                } else if (startedReading) break;
            }
        } catch (IOException e) {
        }
        return negativeFlag ? -val : val;
    }

    int R, C;
    Scanner sc = new Scanner(System.in);
    long[][] comb = new long[64][64];
    long minDist = Long.MAX_VALUE;

    void search(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (minDist <= 1 || diff - comb[v1][R]*comb[v2][R] >= minDist) return;
        if (v1 == R - 1 && v2 == R - 1) {
            if (diff < minDist) minDist = diff;
            return;
        }
        if (v1 >= R) {
            long deltaX = comb[v1][R] - comb[v1-1][R], deltaY = comb[v2][R];
            search(x, y + deltaX*deltaY, v1 - 1, v2);
        }
        if (v2 >= R) {
            long deltaX = comb[v1][R], deltaY = comb[v2][R] - comb[v2-1][R];
            search(x + deltaX*deltaY, y, v1, v2 - 1);
        }
    }

    int[] countA = new int[64], countB = new int[64];
    Map<Long, Long> memoMap = new TreeMap<>();
    char[] seqChars;

    long recurse(long x, long y, int v1, int v2) {
        long key = x*10000 + v1*100 + v2;
        Long cachedVal = memoMap.get(key);
        if (cachedVal != null) return cachedVal;
        long res = 0L;
        long d = Math.abs(x - y);
        if (d - comb[v1][R]*comb[v2][R] > minDist) {
            memoMap.put(key, res);
            return res;
        }
        if (v1 < R || v2 < R) {
            int sumIdx = v1 + v2;
            if (v1 >= countA[sumIdx] && v2 >= countB[sumIdx]) {
                v1 -= countA[sumIdx];
                v2 -= countB[sumIdx];
                res = comb[v1+v2][v1];
                memoMap.put(key, res);
                return res;
            }
            memoMap.put(key, res);
            return res;
        }
        char c = seqChars[v1 + v2 - 1];
        if (c != 'B') {
            long c1 = comb[v1][R] - comb[v1 - 1][R], s2 = comb[v2][R];
            res += recurse(x, y + c1*s2, v1 - 1, v2);
        }
        if (c != 'A') {
            long s1 = comb[v1][R], c2 = comb[v2][R] - comb[v2-1][R];
            res += recurse( x + s1*c2, y, v1, v2 - 1);
        }
        memoMap.put(key, res);
        return res;
    }

    void process() {
        R = sc.nextInt(); C = sc.nextInt(); sc.nextLine();
        seqChars = sc.nextLine().toCharArray();
        for (int i = 0; i <= 2*(R + C); i++)
            for (int j = 0; j <= 2*(R + C); j++) {
                if (j == 0) comb[i][j] = 1;
                else if (i == 0) comb[i][j] = 0;
                else comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
            }
        int v1 = R + C, v2 = R + C;
        long xCoord = 0, yCoord = 0;
        while (v1 >= R && v2 >= R) {
            if (xCoord > yCoord) {
                long c1 = comb[v1][R] - comb[v1 - 1][R], s2 = comb[v2][R];
                yCoord += c1 * s2;
                v1--;
            } else {
                long s1 = comb[v1][R], c2 = comb[v2][R] - comb[v2-1][R];
                xCoord += s1 * c2;
                v2--;
            }
        }
        minDist = Math.abs(xCoord - yCoord);
        search(0, 0, R + C, R + C);
        for (int i = 0; i < 2*(R+C); i++) {
            countA[i + 1] = countA[i] + (seqChars[i] == 'A' ? 1 : 0);
            countB[i + 1] = countB[i] + (seqChars[i] == 'B' ? 1 : 0);
        }
        long ans = recurse(0, 0, R + C, R + C);
        System.out.println(ans);
    }

    public static void main(String[] args) {
        new Test().process();
    }
}
